#pragma once

#include <cstdint>
#include <optional>
#include <string>

namespace tokenspeed {

// The one classification of a cache group, declared by the Python recipe and
// read by every scheduler decision that depends on what a group's blocks hold:
//
//   kFull           rows of token history that are never reclaimed while the
//                   request lives; prefix-closed and shared.
//   kSlidingWindow  rows of token history of which only the trailing
//                   sliding_window_tokens stay resident (SWA kv, compressor
//                   tails, whatever a kernel calls its buffer).
//   kState          whole recurrent states (GDN / KDA linear attention, conv
//                   columns): a block covers no token span, the table is two
//                   slots (input checkpoint, live block), nothing slides out,
//                   and the PD destination layout is a LatestSnapshot.
enum class AttnKind { kFull, kSlidingWindow, kState };

enum class CacheTransferPolicy {
    Unspecified,
    FullSuffix,
    LatestSnapshot,
};

struct CacheGroupConfig {
    std::string group_id;
    // kFull / kSlidingWindow: tokens covered by one block-table slot; the
    // Python row geometry folds to this span before crossing the bridge, and
    // the scheduler never sees rows or strides. kState carries 0: a state
    // block positions nothing (Validate rejects a span on a State group).
    std::int32_t block_granularity{};
    // Scheduler-facing (virtual) block count including the null block: the
    // physical page count of one rank times shard_count, as the Python
    // contract's virtual_block_counts publishes it.
    std::int32_t total_pages{};
    // Scheduler-facing children per LCM block: the physical packing times
    // shard_count (the contract's virtual_packing). Each of the shard_count
    // owners holds one physical child for every shard_count virtual ones.
    std::int32_t cache_blocks_per_lcm_block{1};
    AttnKind attn_kind{AttnKind::kFull};
    // Set exactly for kSlidingWindow.
    std::optional<std::int32_t> sliding_window_tokens{};
    // A kSlidingWindow group whose rows are regenerated by bounded replay
    // instead of being prefix-cached: it is never matched, published or
    // streamed, while its window still slides pages out. Before a local
    // prefix hit the scheduler re-feeds the group's whole window (the largest
    // sliding_window_tokens over all replayable groups) and never leaves a
    // prompt's final chunk shorter than it, so every page the group retains
    // -- and PD transfers, like any sliding window's retained tail -- is
    // regenerated; the decode role re-feeds nothing. False keeps the group an
    // ordinary cached window.
    bool replayable{false};
    CacheTransferPolicy transfer_policy{CacheTransferPolicy::Unspecified};
    // Cyclic owners of this group's virtual blocks; the pool balances new
    // children across them by request load. 1 keeps the group replicated.
    std::int32_t shard_count{1};
    // State checkpoints may only be reused/published at multiples of this
    // token count and must be produced by prefill. 1 preserves arbitrary
    // natural checkpoints, including decode endpoints. No row span.
    std::int32_t checkpoint_granularity{1};

    void Validate() const;
    // Validate() without the total_pages check: every field the capacity
    // model reads, so a group can be sized before its pages exist.
    void ValidateCapacityInputs() const;
};

}  // namespace tokenspeed
